import random,sys
S={'and1':"",
'and2':""}
def frac(s,k):
    p=[i for i,c in enumerate(s) if c=='Y']
    return sum(any(0<abs(i-j)<=k for j in p) for i in p)/len(p)
for n,s in S.items():
    print(n,len(s),s.count('Y'),round(s.count('Y')/len(s),4))
    for k in range(1,6):
        o=frac(s,k);r=random.Random(0);L=list(s);v=[]
        for _ in range(2000): r.shuffle(L);v.append(frac(L,k))
        m=sum(v)/len(v);sd=(sum((x-m)**2 for x in v)/(len(v)-1))**.5
        p=(1+sum(x>=o for x in v))/2001
        print(' k',k,round(o,3),round(m,3),round((o-m)/sd,2),round(p,4))
print('---gap metric')
def g(s,d):
    p=[i for i,c in enumerate(s) if c=='Y'];gs=[b-a for a,b in zip(p,p[1:])]
    return sum(x<=d for x in gs)/len(gs)
for n,s in S.items():
  for d in range(1,8):
    o=g(s,d);r=random.Random(1);L=list(s);v=[]
    for _ in range(2000): r.shuffle(L);v.append(g(L,d))
    m=sum(v)/len(v);sd=(sum((x-m)**2 for x in v)/(len(v)-1))**.5
    print(n,'d',d,round(o,3),round(m,3),round((o-m)/sd,2),round((1+sum(x>=o for x in v))/2001,4))
